INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('73177ca4-92dc-5f7e-ac02-c8812116bba0', 'e0030000-0000-4000-8000-000000000103', 'published', 'Domek Mobilny 35', 'PL', 35, NULL, 'Domek na stalowej ramie o wymiarach 10 x 3,5 m (35 m²) z zadaszonym wejściem, przeznaczony dla 4 osób. Składa się z trzech pomieszczeń: części wypoczynkowo-sypialnianej z aneksem kuchennym, sypialni i łazienki. Dom można z łatwością wielokrotnie przestawiać. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez wyposażenia i sprzętu. Układ pomieszczeń ustala klient.', 'pod-klucz', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mobilny', NULL, 1, 1, 1, NULL, 'Dach płaski', 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24 o przekroju 200x60 mm, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne). Podłoga: płyta OSB z panelem winylowym.', NULL, 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych.', 'EUR', NULL, NULL, false, '2026-10-26T12:57:38.342Z'::timestamptz, '2026-10-26T13:06:18.371Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"domek-mobilny-room-0","name":"Część wypoczynkowo-sypialniana z aneksem kuchennym, sypialnia i łazienka","areaM2":35,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'domek-mobilny-35', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('2010baf0-56d3-5c16-a7a1-ff953e825d8b', 'e0030000-0000-4000-8000-000000000103', 'published', 'Dworek 65', 'PL', 65, NULL, 'Parterowy dom o powierzchni 65 m² w formie dworku, z frontonem i kolumnami przy wejściu. Wysokość ściany w szczycie wynosi około 4 m, a ściany bocznej około 3 m. W domu są salon z aneksem kuchennym, łazienka i sypialnia. Ściany ocieplono 20 cm wełny mineralnej, wszystkie szyby w oknach i drzwiach to bezpieczne szkło VSG, a drzwi wejściowe są antywłamaniowe i przystosowane dla osób niepełnosprawnych. W cenie jest klimatyzacja GREE z funkcją chłodzenia i grzania oraz rekuperator ścienny. Cena nie obejmuje wyposażenia i sprzętu.', 'pod-klucz', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'caloroczny', NULL, 1, 1, 1, NULL, 'Dach dwuspadowy z frontonem, pokrycie: blachodachówka', 'Ściany ocieplone 20 cm wełny mineralnej. Podłoga: blacha trapezowa (myszownica), 20 cm wełny, płyta OSB 22 mm, wykończenie panelem winylowym lub wykładziną. Dach pokryty blachodachówką.', NULL, 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje.', 'EUR', NULL, NULL, false, '2026-10-26T13:06:19.107Z'::timestamptz, '2026-10-26T13:06:19.242Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna 20 cm.","ventilation":"rekuperacja","wallBuildUp":"Ściany ocieplone 20 cm wełny mineralnej.","windowClass":"Szyby VSG (bezpieczne) we wszystkich oknach i drzwiach.","heatSourceOther":"Klimatyzacja GREE z funkcją grzania i chłodzenia.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"inne","heatTransferCoefficients":"nieznana","constructionTechnologyOther":"Brak danych w ofercie producenta."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"dworek-room-0","name":"Salon z aneksem kuchennym, łazienka i sypialnia","areaM2":65,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'dworek-65', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('698d8bfe-952a-4556-a7dd-4924c5f63bbc', '73177ca4-92dc-5f7e-ac02-c8812116bba0', 'en', 'Domek Mobilny 35', 'A cabin on a steel frame measuring 10 x 3.5 m (35 m²) with a covered entrance, designed for 4 people. It has three rooms: a living and sleeping area with a kitchenette, a bedroom and a bathroom. The house can easily be moved many times. The price includes electrical and plumbing installations made to current standards, without furnishings and appliances. The client decides the room layout.', '2026-10-26T12:57:38.342Z'::timestamptz, '2026-10-26T13:06:18.859Z'::timestamptz, '[{"id":"domek-mobilny-room-0","name":"Living and sleeping area with kitchenette, bedroom and bathroom"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, 200x60 mm section, insulation of choice (PUR foam, mineral wool or wood fibre). Floor: OSB board with vinyl panels.', 'Flat roof', 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('59c01bc3-8fd8-459c-a6fb-8ddc20739c92', '73177ca4-92dc-5f7e-ac02-c8812116bba0', 'de', 'Domek Mobilny 35', 'Ein Haus auf Stahlrahmen mit den Maßen 10 x 3,5 m (35 m²) und überdachtem Eingang, ausgelegt für 4 Personen. Es besteht aus drei Räumen: einem Wohn- und Schlafbereich mit Küchenzeile, einem Schlafzimmer und einem Bad. Das Haus lässt sich problemlos mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Ausstattung und Geräte. Die Raumaufteilung bestimmt der Kunde.', '2026-10-26T12:57:38.342Z'::timestamptz, '2026-10-26T13:06:18.859Z'::timestamptz, '[{"id":"domek-mobilny-room-0","name":"Wohn- und Schlafbereich mit Küchenzeile, Schlafzimmer und Bad"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Querschnitt 200x60 mm, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser). Boden: OSB-Platte mit Vinylpaneelen.', 'Flachdach', 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('ad1ccd36-cd33-4677-bc91-45c6e3c92a98', '73177ca4-92dc-5f7e-ac02-c8812116bba0', 'nl', 'Domek Mobilny 35', 'Een huisje op een stalen frame van 10 x 3,5 m (35 m²) met overdekte ingang, bedoeld voor 4 personen. Het bestaat uit drie ruimtes: een woon- en slaapgedeelte met keukenhoek, een slaapkamer en een badkamer. Het huis kan gemakkelijk meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder inrichting en apparatuur. De klant bepaalt de indeling.', '2026-10-26T12:57:38.342Z'::timestamptz, '2026-10-26T13:06:18.859Z'::timestamptz, '[{"id":"domek-mobilny-room-0","name":"Woon- en slaapgedeelte met keukenhoek, slaapkamer en badkamer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, doorsnede 200x60 mm, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel). Vloer: OSB-plaat met vinylpanelen.', 'Plat dak', 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('5c504463-01f2-45f6-ab6f-8f3535968e1f', '2010baf0-56d3-5c16-a7a1-ff953e825d8b', 'en', 'Dworek 65', 'A single-storey 65 m² house in the form of a manor, with a pediment and columns at the entrance. The wall height at the gable is about 4 m and at the side wall about 3 m. The house has a living room with a kitchenette, a bathroom and a bedroom. Walls are insulated with 20 cm of mineral wool, all window and door glazing is safe VSG glass, and the entrance door is burglar-resistant and adapted for people with disabilities. The price includes GREE air conditioning with cooling and heating and a wall-mounted heat recovery unit. The price does not include furnishings and appliances.', '2026-10-26T13:06:19.107Z'::timestamptz, '2026-10-26T13:06:19.107Z'::timestamptz, '[{"id":"dworek-room-0","name":"Living room with kitchenette, bathroom and bedroom"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Walls insulated with 20 cm of mineral wool. Floor: trapezoidal sheet (checker plate), 20 cm of wool, 22 mm OSB board, finished with vinyl panels or carpet. Roof covered with metal roof tiles.', 'Gable roof with a pediment, covering: metal roof tiles', 'The client decides the final room layout, and the producer is open to the client''s proposals.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('29348384-7985-49e5-ac52-1aa1855c9550', '2010baf0-56d3-5c16-a7a1-ff953e825d8b', 'de', 'Dworek 65', 'Ein eingeschossiges Haus mit 65 m² in Form eines Gutshauses, mit Giebel und Säulen am Eingang. Die Wandhöhe am Giebel beträgt etwa 4 m, an der Seitenwand etwa 3 m. Im Haus befinden sich ein Wohnraum mit Küchenzeile, ein Bad und ein Schlafzimmer. Die Wände sind mit 20 cm Mineralwolle gedämmt, alle Scheiben in Fenstern und Türen sind sicheres VSG-Glas, und die Eingangstür ist einbruchhemmend und behindertengerecht. Im Preis enthalten sind eine GREE-Klimaanlage mit Kühl- und Heizfunktion sowie ein Wandlüftungsgerät mit Wärmerückgewinnung. Der Preis enthält keine Ausstattung und Geräte.', '2026-10-26T13:06:19.107Z'::timestamptz, '2026-10-26T13:06:19.107Z'::timestamptz, '[{"id":"dworek-room-0","name":"Wohnzimmer mit Küchenzeile, Bad und Schlafzimmer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Wände mit 20 cm Mineralwolle gedämmt. Boden: Trapezblech (Riffelblech), 20 cm Wolle, OSB-Platte 22 mm, Abschluss mit Vinylpaneelen oder Teppichboden. Dach mit Blechdachziegeln gedeckt.', 'Satteldach mit Giebelfront, Eindeckung: Blechdachziegel', 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('6a6bdcde-5df6-4ea9-89a2-26edfd490cbf', '2010baf0-56d3-5c16-a7a1-ff953e825d8b', 'nl', 'Dworek 65', 'Een gelijkvloerse woning van 65 m² in de vorm van een landhuis, met fronton en kolommen bij de ingang. De wandhoogte bij de gevelpunt bedraagt ongeveer 4 m en bij de zijwand ongeveer 3 m. In het huis zijn een woonkamer met keukenhoek, een badkamer en een slaapkamer. De wanden zijn geïsoleerd met 20 cm minerale wol, alle beglazing in ramen en deuren is veilig VSG-glas en de voordeur is inbraakwerend en aangepast voor mensen met een beperking. In de prijs zijn een GREE-airconditioning met koel- en verwarmfunctie en een wandventilatie-unit met warmteterugwinning inbegrepen. De prijs omvat geen inrichting en apparatuur.', '2026-10-26T13:06:19.107Z'::timestamptz, '2026-10-26T13:06:19.107Z'::timestamptz, '[{"id":"dworek-room-0","name":"Woonkamer met keukenhoek, badkamer en slaapkamer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Wanden geïsoleerd met 20 cm minerale wol. Vloer: trapeziumplaat (strekmetaal), 20 cm wol, OSB-plaat 22 mm, afgewerkt met vinylpanelen of tapijt. Dak bedekt met metalen dakpannen.', 'Zadeldak met fronton, dekking: metalen dakpannen', 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_country_eligibility" ("product_id", "country_code", "status", "reason", "created_at", "updated_at") VALUES ('73177ca4-92dc-5f7e-ac02-c8812116bba0', 'PL', 'conditional', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', '2026-10-26T12:57:38.342Z'::timestamptz, '2026-10-26T13:06:18.859Z'::timestamptz) ON CONFLICT DO NOTHING;
